from pathlib import Path
import json,re

TASK="DEV-PRED-ASTRA-AUTONOMOUS-REVIEWER-FIRSTFAIL-20261005"
paths=[
    Path.home()/".local/state/prediction-project-executor"/f"{TASK}.json",
    Path.home()/"prediction_research_prod"/"control/results"/TASK/"RESULT.json",
    Path.home()/"prediction_research_prod"/"control/results"/TASK/"stdout.log",
    Path.home()/"prediction_research_prod"/"control/results"/TASK/"stderr.log",
]
pat=re.compile(r"(FAILURES|FAILED|AssertionError|assert |E\s+|short test summary|Traceback|ERROR)",re.I)

def strings(obj, prefix="root"):
    if isinstance(obj,str):
        yield prefix,obj
    elif isinstance(obj,dict):
        for k,v in obj.items():
            yield from strings(v,f"{prefix}.{k}")
    elif isinstance(obj,list):
        for i,v in enumerate(obj):
            yield from strings(v,f"{prefix}[{i}]")

print("TARGET_TASK="+TASK)
found=False
for p in paths:
    print(f"PATH={p} EXISTS={p.exists()}")
    if not p.exists() or not p.is_file():
        continue
    found=True
    raw=p.read_text(encoding="utf-8",errors="replace")
    candidates=[]
    try:
        obj=json.loads(raw)
        candidates=list(strings(obj))
    except Exception:
        candidates=[("raw",raw)]
    emitted=0
    for label,text in candidates:
        lines=text.splitlines()
        hits=[i for i,line in enumerate(lines) if pat.search(line)]
        if not hits:
            continue
        print("FIELD="+label)
        # Prefer first explicit failure header/failed test, then include enough traceback context.
        i=hits[0]
        for j in range(max(0,i-18), min(len(lines),i+95)):
            print(lines[j][:3000])
        print("FIELD_END")
        emitted += 1
        if emitted >= 4:
            break
    if emitted==0:
        lines=raw.splitlines()
        print("NO_MARKER_TAIL_BEGIN")
        for line in lines[-120:]:
            print(line[:3000])
        print("NO_MARKER_TAIL_END")
print("FOUND_ANY="+str(found))
